likenessToolDescription:function(){return"Here you will find content that looks like you but may have been significantly edited or generated by AI."},
whatLikenessToolDoes:function(){return"You can request to have the content removed based on our\n  <privacy-guidelines-link>Privacy Guidelines</privacy-guidelines-link>. Note that the content can\n  be removed only if it meets a\n  <protecting-identity-link>set of criteria</protecting-identity-link>."},
